function computeRebuildPlan(layers, changedInputs) {
  const rebuilds = [];
  let cascading = false;
  for (const layer of layers) {
    const inputsChanged = layer.inputs.some((i) => changedInputs.has(i));
    if (inputsChanged || cascading) {
      rebuilds.push(layer.name);
      cascading = true;
    }
  }
  return rebuilds;
}
